style.css:
@-moz-document url-prefix("https://ebanking.ing.be/banking/") {
/* Fond global */
    body {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Fonds principaux en sombre */
    .card, .Card, .box, .Box, .panel, .Panel, .Widget, [class*="container"] {
        background-color: #1e1e1e !important;
        border: 1px solid #333 !important;
    }

    /* Texte par défaut clair */
    p, span, div, td, th, li, label {
        color: #e0e0e0 !important;
    }

    /* Titres orange */
    h1, h2, h3, h4, h5, h6 {
        color: #ff9800 !important;
    }

    /* Alternance des lignes de tableau */
    tr:nth-child(even), [class*="row"]:nth-child(even) {
        background-color: #181818 !important;
    }
    tr:nth-child(odd), [class*="row"]:nth-child(odd) {
        background-color: #1e1e1e !important;
    }

    /* Boutons */
    button, input[type="submit"], .btn, .Button {
        background-color: #ff9800 !important;
        color: #000 !important;
        border: none !important;
    }
    button:hover, input[type="submit"]:hover, .btn:hover, .Button:hover {
        background-color: #ffa733 !important;
    }

    /* --- RÈGLE SPÉCIALE --- 
       Si un bloc reste blanc → forcer le texte en noir */
    [style*="background-color: #fff"],
    [style*="background:#fff"],
    [style*="background-color: rgb(255, 255, 255)"],
    [style*="background: rgb(255, 255, 255)"],
    .white-bg, .bg-white {
        color: #000 !important;
    }
}
